import numpy as np
from scipy.stats import spearmanr

# 1. Statistical Metric: Mean Squared Error (MSE)
def calculate_mse(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)

# 2. Ranking Metric: Spearman Rank Correlation (Rank IC)
def calculate_rank_ic(y_true, y_pred):
    # Assumes y_true and y_pred are 2D arrays (time_steps x assets)
    ics = []
    for t in range(len(y_true)):
        rho, _ = spearmanr(y_true[t], y_pred[t])
        if not np.isnan(rho):
            ics.append(rho)
    return np.mean(ics)

# 3. Economic Metric: Simple Vol-Targeted Portfolio Sharpe
def evaluate_portfolio_sharpe(returns, vol_forecasts, target_vol=0.10):
    # Simple inverse-volatility weighting (risk parity style)
    weights = 1.0 / (vol_forecasts + 1e-8)
    weights = weights / np.sum(weights, axis=1, keepdims=True)

    # Portfolio returns
    port_returns = np.sum(weights * returns, axis=1)

    # Annualised Sharpe Ratio (assuming weekly data)
    mean_ret = np.mean(port_returns)
    std_ret = np.std(port_returns) + 1e-8
    return (mean_ret / std_ret) * np.sqrt(52)
